/* slide-studio table header */
#stage table { --header: #174b78; }

/* slide-studio title header */
#stage .slide:is(.cover, .section-slide) { --header: #174b78; }

/* slide-studio heading options */
:root { --heading-mode: fill; --heading-rule-style: solid; --heading-rule-width: 2px; --heading-rule-inset: 44px; }
#stage .slide > h2 { margin-inline:calc(-1 * var(--content-inset)); width:auto; max-width:none; padding-inline:calc(var(--content-inset) + var(--text-pad)); border-radius:0; }
#stage .slide > h2 { background:var(--header-fill, var(--header)); border:0; box-shadow:none; }
#stage .slide > h2, #stage .slide > h2 * { color:var(--header-ink); }
#stage .slide > h2::after { display:none; }
/* end heading options */

/* slide-studio heading fill */
:root { --header-fill: var(--header); }
#stage h2 { background: var(--header-fill); }
#stage h2, #stage h2 * { color: var(--header-ink); }
#stage .cover .cover-title, #stage .cover .cover-title p { color: var(--header); }

