cases.css:
/* 青系の既定テーマ（グラデーションの枠＋白い面）。骨格は runtime/base.css、発表固有の調整は styles/slides.css。 */
:root {
  --ink: #233244;
  --link: #2167a8;
  --accent: #2167a8;
  --header: #1d4a94;
  --muted: #667483;
  --warn: #c0392b;
  --good: #27804f;
  --mark: #fff0b8;
  --mark-ink: #754500;
  --mark-line: #e7b54b;
  --paper: #ffffff;
  --rule: #c4d8e8;
  --header-ink: #ffffff;
  --font-body: "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;
  --font-head: "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;
}
:root{--theme-ink:var(--ink);--theme-muted:var(--muted);--theme-accent:var(--accent);--theme-header:var(--header);--theme-rule:var(--rule);--theme-paper:var(--paper);--theme-border:var(--rule)}
:root{--citation-ink:#64788a}
.reveal{font-family:var(--font-body);color:var(--ink);font-size:29px}
.reveal-viewport{background:var(--paper)}
.reveal h1,.reveal h2,.reveal h3{font-family:var(--font-head);color:var(--ink);font-weight:650;text-transform:none;letter-spacing:0;line-height:1.35}
.reveal h2{font-size:1.35em;color:var(--header);background:none;border:0;margin-bottom:12px}
.reveal h3{font-size:1em}
.reveal strong{color:var(--accent)}
.reveal a{color:var(--link)}
.reveal .kicker{font-size:.55em;letter-spacing:.13em;color:var(--accent);margin-bottom:12px}
.reveal .cover-title{font-family:var(--font-head);font-size:1.9em;line-height:1.5;margin-top:56px}
.reveal .cover-sub{font-size:.9em;color:var(--muted);margin-top:30px}
.reveal table{font-size:.85em;width:auto;max-width:100%;line-height:1.6}
.reveal table td,.reveal table th{padding:16px 8px;border-bottom:1px solid #ced5dc}
.reveal .slide-number{left:20px;right:auto;bottom:16px;background:none;color:var(--muted);font-size:14px}
.reveal .progress{color:var(--accent)}
.reveal .slide-number{width:auto!important;left:65px!important;right:auto!important;pointer-events:none}
.reveal .slides section.slide::after{
  content:"";position:absolute;left:0;right:0;bottom:-4px;
  border-top:2px solid var(--rule);pointer-events:none;
}
.reveal .cover-title{color:var(--header)}
.reveal .cover .kicker{border-top:6px solid var(--header);padding-top:18px}
.reveal table th{color:var(--header);background:#edf5fc}
.reveal .slide-number{color:var(--header)}
.reveal .slide-number a{color:inherit}
@media print{
  #stage .slide::before,#stage .slide::after,#stage .slide>h2::before,#stage .section-slide h1,.reveal .cover .kicker,.reveal table th{
    -webkit-print-color-adjust:exact;print-color-adjust:exact;
  }
}
.reveal{font-size:29px;line-height:1.3}
#stage h2{font-size:1.35em;line-height:1.35;margin-top:0}
#stage .cover{padding-top:0}
#stage table{font-size:.85em;margin:0;border-collapse:collapse}
#stage .cover p{color:var(--header)}
#stage .page-number{left:auto;right:calc(var(--frame) + 24px);bottom:0;height:var(--frame);display:flex;align-items:center;font-size:14px;line-height:1;font-variant-numeric:tabular-nums;letter-spacing:.04em;color:#fff}
#stage .cover .cover-title{margin-top:140px;font-size:80px;font-weight:650;line-height:1.55;letter-spacing:.015em}
#stage .cover .cover-title::before{content:'';display:block;width:92px;height:5px;background:var(--frame-fill);margin-bottom:28px}
#stage .cover p{color:var(--header)}
#stage table{border-top:2px solid #4b86b4;border-bottom:1px solid #b8cedf}
#stage table th{background:#e8f1f8;color:var(--header);font-weight:650}
#stage table tbody tr:nth-child(even){background:#f7fafd}
#stage table td{border-bottom:1px solid #dce6ee}
#toolbar button{background:#fffffff0;border:1px solid #cad9e5;box-shadow:0 2px 10px #14395312;color:#174b78}
#overview{background:#edf3f8}
.thumb{border-top-color:#2167a8;box-shadow:0 3px 12px #174b7810}
.thumb[aria-current=true]{background:#dcebf6}
:root{--reference-rule:#e4edf4}

/* block palette v4: 整理・結論・補足・引用・定義・メモ */
