/* 表紙の既定位置（タイトルの上余白・発表者までの間隔） */
#stage .slide.cover { --cover-title-top:140px; --cover-authors-gap:44px; }
#stage .slide.cover .cover-title { margin-top:var(--cover-title-top); left:0; top:0; }
#stage .slide.cover .cover-subtitle { left:0; top:0; }
#stage .slide.cover .cover-authors { margin-top:var(--cover-authors-gap); left:0; top:0; }

/* 枠：全面のグラデーションに、角丸の面を重ねる。面の色は各ページの背景の設定に従う。 */
