/* 表紙の既定位置（タイトルの上余白・発表者までの間隔） */
#stage .slide.cover { --cover-title-top:140px; --cover-authors-gap:44px; }
#stage .slide.cover .cover-title { margin-top:var(--cover-title-top); left:0; top:0; }
#stage .slide.cover .cover-subtitle { left:0; top:0; }
#stage .slide.cover .cover-authors { margin-top:var(--cover-authors-gap); left:0; top:0; }

/* 枠：全面のグラデーションに、角丸の面を重ねる。面の色は各ページの背景の設定に従う。 */
#stage .slide{--frame:26px;--frame-radius:30px;--frame-fill:linear-gradient(100deg,#3f8a9c,var(--header));--panel:var(--background-fill,var(--paper));--content-inset:52px;isolation:isolate}
#stage .slide.cover{--panel:var(--cover-fill,var(--paper))}
#stage .slide.section-slide{--panel:var(--section-fill,var(--paper))}
/* 上の帯の右端に、薄い順に並ぶ小さな四角 */
#stage .slide::before{content:'';position:absolute;inset:0;z-index:-2;pointer-events:none;
  background:linear-gradient(#ffffffd0 0 0) right calc(var(--frame) + 24px) top calc((var(--frame) - 10px) / 2)/10px 10px no-repeat,linear-gradient(#ffffff80 0 0) right calc(var(--frame) + 50px) top calc((var(--frame) - 10px) / 2)/10px 10px no-repeat,linear-gradient(#ffffff40 0 0) right calc(var(--frame) + 76px) top calc((var(--frame) - 10px) / 2)/10px 10px no-repeat,var(--frame-fill)}
#stage section.slide::after{content:'';position:absolute;inset:var(--frame);bottom:var(--frame)!important;z-index:-1;border:0;border-radius:var(--frame-radius);pointer-events:none;background:var(--panel)}
#stage h2{color:var(--header);background:none;border:0;box-shadow:none}
#stage section.slide>h2{position:relative;margin:calc(var(--frame) + 8px) calc(var(--frame) - var(--content-inset)) 10px;padding:0 calc(var(--content-inset) - var(--frame) + var(--text-pad))}
/* 見出しの左の二本の棒 */
#stage section.slide>h2::before{content:'';position:absolute;left:10px;top:calc(.675em - 17px);width:18px;height:34px;
  background:linear-gradient(#3f8a9c 0 0) 0 0/7px 100% no-repeat,linear-gradient(var(--header) 0 0) 11px 100%/7px 60% no-repeat}
#stage .citations{right:var(--content-inset);bottom:calc(var(--frame) + 4px)}
#stage .footnote-small{bottom:calc(var(--frame) + 8px)}
/* 章の扉：左の枠から伸びる色付きの長方形に、大きな番号と白い見出し */
#stage .section-slide{padding:212px var(--content-inset) 0;color:var(--ink)}
#stage .section-slide h1{position:relative;display:flex;align-items:center;gap:44px;min-height:296px;margin:0 96px 0 calc(var(--frame) - var(--content-inset));padding:40px 64px 40px calc(var(--content-inset) - var(--frame) + 36px);border-radius:0 20px 20px 0;background:var(--frame-fill);color:var(--header-ink);font-size:60px;font-weight:650;line-height:1.4;letter-spacing:.035em}
#stage .section-slide h1::before{content:none}
#stage .section-slide .chapter-number{position:static;flex:none;margin:0;padding:0 44px 0 0;border-right:2px solid #ffffff66;color:var(--header-ink);font-size:144px;font-weight:700;line-height:1;letter-spacing:.02em}
/* 表紙と章の扉：帯の四角の代わりに、面の右下へ段になった長方形 */
#stage .slide:is(.cover,.section-slide)::before{background:var(--frame-fill)}
#stage section.slide:is(.cover,.section-slide)::after{background:linear-gradient(var(--header) 0 0) 100% 100%/58px 86px no-repeat,linear-gradient(#8fbcc8 0 0) 100% 100%/118px 56px no-repeat,linear-gradient(#d5e5ea 0 0) 100% 100%/178px 26px no-repeat,var(--panel)}
/* 表紙の短い線はタイトルの左端にそろえる */
#stage .slide.cover .cover-title::before{left:var(--cover-inset);right:auto;margin:0}

/* slide-studio table header */
#stage table { --header: #1d4a94; }

/* slide-studio title header */
#stage .slide:is(.cover, .section-slide) { --header: #1d4a94; }

/* slide-studio heading options */
:root { --heading-mode: fill; --heading-rule-style: solid; --heading-rule-width: 2px; --heading-rule-inset: 44px; }
#stage .slide > h2 { margin-inline:calc(-1 * var(--content-inset)); width:auto; max-width:none; padding-inline:calc(var(--content-inset) + var(--text-pad)); border-radius:0; }
