/* graphite：チャコールの方眼、太い白文字、オレンジのアクセント。
   色の値は :root の変数だけに書き、ほかの色は変数から作る（テーマの色を直すと全体が付いてくる）。 */
:root {
  --ink: #eeeeec;
  --link: #7cb4ff;
  --accent: #ff9b54;
  --header: #ffffff;
  --muted: #b8b8b5;
  --warn: #ff9a8f;
  --good: #8fd3a5;
  --mark: #51351f;
  --mark-ink: #ffffff;
  --mark-line: #ff9b54;
  --paper: #262626;
  --rule: #50504e;
  --header-ink: #262626;
  --font-head: "Helvetica Neue","Hiragino Sans","Yu Gothic",sans-serif;
  --font-body: "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;
}
:root{--theme-ink:var(--ink);--theme-muted:var(--muted);--theme-accent:var(--accent);--theme-header:var(--header);--theme-rule:var(--rule);--theme-paper:var(--paper);--theme-border:var(--rule)}
.reveal{font-family:var(--font-body);color:var(--ink);font-size:29px;line-height:1.3}
#stage a{color:var(--link)}
#stage h3{font-size:1em;font-weight:700;color:var(--header)}
/* 方眼は背景だけに描き、本文や図の配置を変えない。 */
#stage{background:var(--ink)}
#stage .slide{border-radius:0;background-color:var(--paper);background-image:linear-gradient(color-mix(in srgb,var(--rule) 58%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--rule) 58%,transparent) 1px,transparent 1px);background-size:40px 40px;background-position:0 0}

/* 見出し：太い白字、全幅の罫線とオレンジの短い線 */
#stage h2{position:relative;font-size:1.25em;line-height:1.3;font-weight:800;letter-spacing:.06em;color:var(--header);background:none;border:0;border-bottom:2px solid var(--header);margin-top:0;margin-bottom:14px;padding:16px calc(var(--content-inset) + var(--text-pad)) 9px}
#stage h2::before{content:'';position:absolute;left:calc(var(--content-inset) + var(--text-pad));bottom:-2px;width:64px;height:4px;background:var(--accent)}

/* 表紙：左の縦線、題名の下線、著者名を囲む白い帯。 */
#stage .cover{padding-top:0}
#stage .cover::before{content:'';position:absolute;left:40px;top:0;bottom:0;width:2px;background:var(--header);pointer-events:none}
#stage .cover .cover-title{margin-top:100px;font-size:64px;font-weight:800;line-height:1.45;letter-spacing:.06em;color:var(--header)}
#stage .slide.cover div.cover-title{padding:48px 44px 80px}
#stage .slide.cover .cover-title::before{content:none}
#stage .slide.cover .cover-title::after{content:'';left:44px;right:44px;bottom:16px;width:auto;height:4px;background:var(--accent)}
#stage .cover p{color:var(--muted);font-size:.78em;letter-spacing:.08em}
#stage .cover .cover-title p{color:inherit;font-size:inherit;letter-spacing:inherit}
#stage .slide.cover div.cover-subtitle{margin:12px 0 0;padding:0 44px;background:none;color:var(--ink);font-size:26px;font-weight:700;letter-spacing:.08em}
#stage .cover .cover-subtitle p{color:inherit}
#stage .slide.cover .cover-authors{display:block;box-sizing:border-box;width:calc(100% + 2 * var(--content-inset));max-width:none;margin:40px calc(-1 * var(--content-inset)) 0;padding:20px 88px;background:var(--header);color:var(--header-ink)}
#stage .slide.cover .cover-authors[data-affiliation-position]{justify-content:flex-start}
#stage .slide.cover .cover-authors p{padding:0;color:inherit;letter-spacing:.04em}
#stage .slide.cover .cover-authors::before{content:'';position:absolute;left:40px;top:0;bottom:0;width:2px;background:var(--header-ink);pointer-events:none}

/* 章扉：中央のオレンジ文字。上端の白い本文見出しと区別する。 */
#stage .section-slide{padding:0 var(--content-inset);text-align:center}
#stage .section-slide::before{content:'';position:absolute;left:0;top:0;bottom:0;width:40px;background:var(--header);pointer-events:none}
#stage .section-slide h1{margin-top:240px;padding-inline:48px;font-size:80px;font-weight:800;line-height:1.3;letter-spacing:.06em;color:var(--accent)}
#stage .section-slide h1::before{content:none}
#stage .section-slide h1::after{content:'';display:block;width:96px;height:2px;background:var(--header);margin:30px auto 0}

/* 目次：明るい方眼、黒い文字と番号。 */
#stage section.slide.toc-slide{background-color:var(--ink);background-image:linear-gradient(color-mix(in srgb,var(--rule) 12%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--rule) 12%,transparent) 1px,transparent 1px);background-size:40px 40px;color:var(--paper)}
#stage .toc-slide::before{content:'';position:absolute;left:0;top:0;bottom:0;width:40px;background:var(--paper);pointer-events:none}
#stage section.toc-slide > h2{color:var(--paper);border-bottom-color:var(--paper)}
#stage section.toc-slide > h2::before{content:none}
#stage .toc-slide .toc-list li{border-bottom:0;font-weight:700;align-items:center}
#stage .toc-slide .toc-number{display:inline-flex;align-items:center;justify-content:center;flex:none;width:42px;height:42px;border-radius:50%;background:var(--paper);color:var(--ink);font-weight:700}
#stage .toc-slide .page-number{color:var(--paper)}

/* 表：見出しは小さく字間を空け、行は細い線と薄い縞 */
#stage table{font-size:.85em;width:auto;max-width:100%;line-height:1.6;margin:0;border-collapse:collapse}
#stage table th{background:none;color:var(--muted);font-weight:700;font-size:.85em;letter-spacing:.12em;border-bottom:2px solid var(--accent)}
#stage table td{border-bottom:1px solid var(--rule)}
#stage table tbody tr:nth-child(even){background:color-mix(in srgb,var(--ink) 4%,transparent)}

#stage .page-number{left:auto;right:10px;bottom:8px;font-size:13px;line-height:1.2;font-variant-numeric:tabular-nums;letter-spacing:.2em;color:var(--muted)}
#stage .slide::after{border:0}
#toolbar button{background:var(--paper);border:1px solid var(--rule);color:var(--ink)}
#overview,.thumb{background:var(--paper);color:var(--ink)}
.thumb{border-top-color:var(--accent)}
.thumb[aria-current=true]{outline:2px solid var(--accent);background:var(--paper)}
:root{--summary-paper:var(--paper);--summary-ink:var(--header)}
@media print{#stage .slide,#stage .slide *{-webkit-print-color-adjust:exact;print-color-adjust:exact}}

/* block palette v4: 整理・結論・補足・引用・定義・メモ */
:root {
  --block-border:3.5px solid #9e9e9dff;
  --block-background:#262626ff;
  --block-plain-ink:#eeeeecff;
  --block-plain-radius:10px;
  --block-plain-shadow:0;
  --block-top-line:8px solid #ff9b54ff;
  --block-top-fill:#524237ff;
  --block-top-ink:#eeeeecff;
