  --block-bracket-radius:0px;
  --block-bracket-shadow:0;
  --block-bracket-accent:#dfdb90ff;
  --block-bracket-width:3.5px;
  --block-fold-line:3.5px solid #ff9b54ff;
  --block-fold-fill:#524237ff;
  --block-fold-ink:#eeeeecff;
  --block-fold-radius:10px;
  --block-fold-shadow:0;
  --block-fold-accent:#ff9b54ff;
  --block-fold-width:3.5px;
  --block-unframed-radius:0px; --block-unframed-shadow:0;
}

/* 表紙の既定位置（タイトルの上余白・発表者までの間隔） */
