#stage .cover .cover-title p{color:inherit;font-size:inherit;font-weight:inherit;letter-spacing:inherit}
/* 発表者は囲まず、文字だけで整える */
#stage .cover .cover-authors :is(.cover-names,.cover-name){color:var(--header);font-weight:600;letter-spacing:.06em}
#stage .cover .cover-authors :is(.cover-affiliations,.cover-affiliation){color:var(--muted);font-weight:400;letter-spacing:.04em}
#stage .slide.cover .page-number{color:var(--muted)}

/* # 章扉：白地の対角の隅を広く染め、枠だけの円をアクセントに置いて、題名を中央に濃い青で置く。
   染めの中心（--g1・--g2）は、円を置かない側の隅のページ外にする（円と染めの中心を重ねない）。
   位置を3通りに変えて、並べたときに同じ形が続かないようにする */
#stage .section-slide{--o1:1180px 40px;--o2:860px 110px;--o3:780px 190px;--o4:60px 690px;--o5:250px 560px;--g1:-90px -100px;--g2:1370px 830px;padding:0 var(--content-inset);overflow:hidden;text-align:center;background:
  radial-gradient(circle 820px at var(--g1),var(--wash-blue),color-mix(in srgb,var(--wash-blue) 65%,transparent) 42%,color-mix(in srgb,var(--wash-sky) 32%,transparent) 74%,transparent),
  radial-gradient(circle 760px at var(--g2),var(--wash-lilac),color-mix(in srgb,var(--wash-lilac) 72%,transparent) 42%,color-mix(in srgb,var(--wash-lilac) 28%,transparent) 74%,transparent),
  #fff}
#stage .section-slide::before{inset:0;border:0;border-radius:0;box-shadow:none;background:var(--wash-deep);
  mask-image:radial-gradient(circle 171px at var(--o1),transparent 166.5px,#000 167px,#000 170px,transparent 170.5px),radial-gradient(circle 65px at var(--o2),transparent 60.5px,#000 61px,#000 64px,transparent 64.5px),radial-gradient(circle 23px at var(--o3),transparent 18.5px,#000 19px,#000 22px,transparent 22.5px),radial-gradient(circle 121px at var(--o4),transparent 116.5px,#000 117px,#000 120px,transparent 120.5px),radial-gradient(circle 41px at var(--o5),transparent 36.5px,#000 37px,#000 40px,transparent 40.5px)}
#stage .section-slide:nth-child(3n+1){--o1:100px 40px;--o2:420px 110px;--o3:500px 190px;--o4:1040px 740px;--o5:1200px 590px;--g1:1360px -100px;--g2:-90px 830px}
#stage .section-slide:nth-child(3n+2){--o1:60px 720px;--o2:370px 620px;--o3:450px 540px;--o4:1180px 40px;--o5:1010px 130px;--g1:1370px 830px;--g2:-90px -100px}
#stage .section-slide h1{margin-top:285px;padding-inline:var(--text-pad);font-size:86.4px;font-weight:700;line-height:1.25;letter-spacing:.01em;color:var(--header)}
#stage .section-slide h1::before{content:none}
