cases.palette:
/* mist：空色から薄紫へ移る淡いグラデーションに、半透明の白いパネルを重ねる配色。見出しは中央に大きく、欧文は Avenir。
   色の値は :root の変数だけに書き、ほかの色は変数から作る（テーマの色を直すと全体が付いてくる）。 */
:root {
  --ink: #2a3a4c;
  --link: #1d5e9c;
  --accent: #1d889e;
  --header: #f7f9fc;
  --muted: #525e6b;
  --warn: #9e3527;
  --good: #29654a;
  --mark: #d4eef0;
  --mark-ink: #12414a;
  --mark-line: #5fb3bf;
  --paper: #f7f9fc;
  --rule: #c6d4e2;
  --header-ink: #ffffff;
  /* グラデーションの色。--header と --accent から作る */
  --wash-deep: color-mix(in oklch,var(--header) 65%,#2f8fd8);
  --wash-blue: color-mix(in oklch,var(--header) 30%,#58b0f0);
  --wash-sky: color-mix(in oklch,var(--header) 10%,#b5e0ff);
  --wash-teal: color-mix(in oklch,var(--accent) 70%,#14c2ae);
  --wash-mint: color-mix(in oklch,var(--accent) 18%,#b4f5e4);
  --wash-lilac: color-mix(in oklch,var(--header) 16%,#b8b0ff);
  --wash-aqua: color-mix(in oklch,var(--accent) 22%,#4fd8e6);
  --font-head: "Avenir Next","Hiragino Sans","Yu Gothic",sans-serif;
  --font-body: "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;
}
:root{--theme-ink:var(--ink);--theme-muted:var(--muted);--theme-accent:var(--accent);--theme-header:var(--header);--theme-rule:var(--rule);--theme-paper:var(--paper);--theme-border:var(--rule)}
.reveal{font-family:var(--font-body);color:var(--ink);font-size:29px;line-height:1.3}
#stage a{color:var(--link)}
#stage h3{font-size:1em;font-weight:700;color:var(--header)}
/* 本文のページ：空色から薄紫へ移る斜めのグラデーション1枚 */
#stage .slide{--panel-inset:16px 20px;--panel-radius:20px;isolation:isolate;background:linear-gradient(128deg,color-mix(in oklch,var(--wash-sky) 65%,var(--wash-blue)),color-mix(in oklch,var(--wash-lilac) 85%,var(--wash-deep)) 55%,color-mix(in oklch,var(--wash-mint) 80%,var(--wash-teal)))}

/* 半透明の白いパネル：下の色をわずかに透かす */
#stage .slide::before{content:'';position:absolute;inset:var(--panel-inset);z-index:-1;pointer-events:none;box-sizing:border-box;
  border:1px solid color-mix(in srgb,#fff 80%,transparent);border-radius:var(--panel-radius);
  background:color-mix(in srgb,#fff 88%,transparent);
  box-shadow:0 8px 28px color-mix(in srgb,var(--header) 12%,transparent)}

/* ## 見出し：飾りなしで中央に大きく */
#stage h2{text-align:center;font-size:1.45em;line-height:1.25;font-weight:700;letter-spacing:-.005em;color:var(--header);background:none;border:0;margin-top:0;margin-bottom:8px;padding:34px calc(var(--content-inset) + var(--text-pad)) 0}

/* 表紙：白い余白を主役に、右下を空色・薄紫・ミントで広く染める。
   章扉の円とは異なる、柔らかな光だけの構成。 */
#stage .cover{--panel-inset:0;--panel-radius:0;padding-top:0;overflow:hidden;background:#fff}
#stage .cover::before{inset:0;border:0;border-radius:0;box-shadow:none;background:
  radial-gradient(ellipse 640px 440px at 100% 100%,var(--wash-lilac) 8%,color-mix(in srgb,var(--wash-lilac) 65%,transparent) 48%,transparent 100%),
  radial-gradient(ellipse 710px 390px at 72% 108%,var(--wash-blue),color-mix(in srgb,var(--wash-sky) 75%,transparent) 50%,transparent 100%),
  radial-gradient(ellipse 390px 330px at 105% 56%,var(--wash-mint),transparent 100%)}
/* 表紙の丸：章扉の輪郭線と区別し、右上に淡い塗りの円を重ねる */
#stage .slide.cover::after{content:'';position:absolute;inset:0;z-index:-1;pointer-events:none;border:0;background:
  radial-gradient(circle 46px at calc(100% - 208px) 116px,color-mix(in srgb,var(--wash-mint) 70%,transparent) 98%,transparent 100%),
  radial-gradient(circle 104px at calc(100% - 92px) 64px,color-mix(in srgb,var(--wash-lilac) 48%,transparent) 99%,transparent 100%),
  radial-gradient(circle 24px at calc(100% - 58px) 202px,color-mix(in srgb,var(--wash-blue) 50%,transparent) 97%,transparent 100%)}

/* 表紙：題名の下に空色・ミントの短いバーを添える */
#stage .cover .cover-title{margin-top:195px;font-size:80px;font-weight:700;line-height:1.2;letter-spacing:-.01em;color:var(--header)}
#stage .slide.cover .cover-title::before{content:none}
#stage .slide.cover .cover-title::after{content:'';left:var(--text-pad);right:auto;bottom:0;width:168px;height:7px;margin:0;border-radius:999px;background:linear-gradient(90deg,var(--header),var(--accent) 60%,var(--wash-mint))}
#stage .cover p{color:var(--muted);font-size:.78em;font-weight:500;letter-spacing:.04em}
#stage .cover .cover-title p{color:inherit;font-size:inherit;font-weight:inherit;letter-spacing:inherit}
/* 発表者は囲まず、文字だけで整える */
#stage .cover .cover-authors :is(.cover-names,.cover-name){color:var(--header);font-weight:600;letter-spacing:.06em}
#stage .cover .cover-authors :is(.cover-affiliations,.cover-affiliation){color:var(--muted);font-weight:400;letter-spacing:.04em}
#stage .slide.cover .page-number{color:var(--muted)}

/* # 章扉：白地の対角の隅を広く染め、枠だけの円をアクセントに置いて、題名を中央に濃い青で置く。
   染めの中心（--g1・--g2）は、円を置かない側の隅のページ外にする（円と染めの中心を重ねない）。
   位置を3通りに変えて、並べたときに同じ形が続かないようにする */
#stage .section-slide{--o1:1180px 40px;--o2:860px 110px;--o3:780px 190px;--o4:60px 690px;--o5:250px 560px;--g1:-90px -100px;--g2:1370px 830px;padding:0 var(--content-inset);overflow:hidden;text-align:center;background:
  radial-gradient(circle 820px at var(--g1),var(--wash-blue),color-mix(in srgb,var(--wash-blue) 65%,transparent) 42%,color-mix(in srgb,var(--wash-sky) 32%,transparent) 74%,transparent),
  radial-gradient(circle 760px at var(--g2),var(--wash-lilac),color-mix(in srgb,var(--wash-lilac) 72%,transparent) 42%,color-mix(in srgb,var(--wash-lilac) 28%,transparent) 74%,transparent),
  #fff}
#stage .section-slide::before{inset:0;border:0;border-radius:0;box-shadow:none;background:var(--wash-deep);
  mask-image:radial-gradient(circle 171px at var(--o1),transparent 166.5px,#000 167px,#000 170px,transparent 170.5px),radial-gradient(circle 65px at var(--o2),transparent 60.5px,#000 61px,#000 64px,transparent 64.5px),radial-gradient(circle 23px at var(--o3),transparent 18.5px,#000 19px,#000 22px,transparent 22.5px),radial-gradient(circle 121px at var(--o4),transparent 116.5px,#000 117px,#000 120px,transparent 120.5px),radial-gradient(circle 41px at var(--o5),transparent 36.5px,#000 37px,#000 40px,transparent 40.5px)}
#stage .section-slide:nth-child(3n+1){--o1:100px 40px;--o2:420px 110px;--o3:500px 190px;--o4:1040px 740px;--o5:1200px 590px;--g1:1360px -100px;--g2:-90px 830px}
#stage .section-slide:nth-child(3n+2){--o1:60px 720px;--o2:370px 620px;--o3:450px 540px;--o4:1180px 40px;--o5:1010px 130px;--g1:1370px 830px;--g2:-90px -100px}
#stage .section-slide h1{margin-top:285px;padding-inline:var(--text-pad);font-size:86.4px;font-weight:700;line-height:1.25;letter-spacing:.01em;color:var(--header)}
#stage .section-slide h1::before{content:none}
#stage .section-slide h1::after{content:'';display:block;width:56px;height:14px;background:radial-gradient(circle 7px at 7px 50%,var(--wash-deep) 96%,transparent),radial-gradient(circle 7px at 28px 50%,var(--wash-blue) 96%,transparent),radial-gradient(circle 7px at 49px 50%,var(--wash-teal) 96%,transparent);margin:30px auto 0}

/* 目次：ミントから空色・薄紫へ移る背景に、半透明の白いパネル。左寄せで表紙と変化を付ける */
#stage .slide.toc-slide{background:linear-gradient(145deg,var(--wash-mint),var(--wash-sky) 48%,var(--wash-lilac));--panel-inset:24px 28px;--panel-radius:24px}
#stage .toc-slide > h2{text-align:left;color:var(--header);padding-top:42px;margin-bottom:20px}
#stage .toc-slide .toc-list li{align-items:center;border-bottom-color:var(--rule)}
#stage .toc-slide .toc-number{display:inline-flex;align-items:center;justify-content:center;flex:none;min-width:48px;height:42px;padding:0 6px;box-sizing:border-box;border:0;border-radius:0;background:none;box-shadow:none;color:var(--header);font-weight:700;font-variant-numeric:tabular-nums}
#stage .toc-slide .toc-label{min-width:0}

/* 表：見出しの下に太い線、本文の行は半透明の白 */
#stage table{font-size:.85em;width:auto;max-width:100%;line-height:1.6;margin:0;border-collapse:collapse;background:color-mix(in srgb,#fff 70%,transparent)}
#stage table th{background:none;color:var(--header);font-weight:700;letter-spacing:.04em;border-bottom:2px solid var(--header)}
