  linear-gradient(118deg,transparent 26%,color-mix(in srgb,var(--accent) 9%,transparent) 40%,color-mix(in srgb,var(--night-violet) 15%,transparent) 50%,color-mix(in srgb,var(--accent) 8%,transparent) 59%,transparent 72%),
