#stage .slide.cover .cover-subtitle { left:0; top:0; }
#stage .slide.cover .cover-authors { margin-top:var(--cover-authors-gap); left:0; top:0; }

/* slide-studio table header */
#stage table { --header: #f2f6fc; }

/* slide-studio title header */
#stage .slide:is(.cover, .section-slide) { --header: #f2f6fc; }

/* slide-studio heading options */
:root { --heading-mode: fill; --heading-rule-style: solid; --heading-rule-width: 2px; --heading-rule-inset: 44px; }
#stage .slide > h2 { margin-inline:calc(-1 * var(--content-inset)); width:auto; max-width:none; padding-inline:calc(var(--content-inset) + var(--text-pad)); border-radius:0; }
