cases.palette:
/* night：夜空。星、天の川、青・紫・薄紅の光。細い書体の題名と、光る点・消えていく線の見出し。
   色の値は :root の変数だけに書き、ほかの色は変数から作る（テーマの色を直すと全体が付いてくる）。 */
:root {
  --ink: #dfe7f2;
  --link: #7cc4ff;
  --accent: #7cc4ff;
  --header: #f7f9fc;
  --muted: #95a5ba;
  --warn: #ff9d94;
  --good: #8fdcae;
  --mark: #24405e;
  --mark-ink: #ffffff;
  --mark-line: #7cc4ff;
  --paper: #0f1a31;
  --rule: #2c3d55;
  --header-ink: #0f1a31;
  --font-head: "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;
  --font-body: "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;
}
:root{--theme-ink:var(--ink);--theme-muted:var(--muted);--theme-accent:var(--accent);--theme-header:var(--header);--theme-rule:var(--rule);--theme-paper:var(--paper);--theme-border:var(--rule)}
.reveal{font-family:var(--font-body);color:var(--ink);font-size:29px;line-height:1.3}
#stage a{color:var(--link)}
#stage h3{font-size:1em;font-weight:600;color:var(--header)}
/* 夜空の部品。星は位置・大きさ・明るさをばらし、本文のページには淡い星だけを置く */
:root{
  --night-violet:color-mix(in oklch,var(--accent),#a070ff);
  --night-rose:color-mix(in oklch,var(--accent) 30%,#ff8fcf);
  --night-sky:linear-gradient(175deg,color-mix(in srgb,var(--paper) 80%,#000),var(--paper) 42%,color-mix(in srgb,var(--paper) 88%,var(--night-violet)));
  --night-far:radial-gradient(circle 0.8px at 33% 16%,color-mix(in srgb,var(--ink) 45%,transparent) 60%,transparent),
  radial-gradient(circle 0.8px at 81% 11%,color-mix(in srgb,var(--ink) 43%,transparent) 60%,transparent),
  radial-gradient(circle 1px at 51% 6%,color-mix(in srgb,var(--ink) 38%,transparent) 60%,transparent),
  radial-gradient(circle 1.1px at 25% 54%,color-mix(in srgb,var(--ink) 26%,transparent) 60%,transparent),
  radial-gradient(circle 1px at 14% 23%,color-mix(in srgb,var(--ink) 45%,transparent) 60%,transparent),
  radial-gradient(circle 1.2px at 8% 57%,color-mix(in srgb,var(--ink) 26%,transparent) 60%,transparent),
  radial-gradient(circle 1px at 6% 83%,color-mix(in srgb,var(--ink) 34%,transparent) 60%,transparent),
  radial-gradient(circle 1.1px at 54% 56%,color-mix(in srgb,var(--ink) 42%,transparent) 60%,transparent),
  radial-gradient(circle 0.9px at 19% 57%,color-mix(in srgb,var(--ink) 45%,transparent) 60%,transparent),
  radial-gradient(circle 0.8px at 11% 69%,color-mix(in srgb,var(--ink) 43%,transparent) 60%,transparent),
  radial-gradient(circle 1.1px at 92% 66%,color-mix(in srgb,var(--ink) 38%,transparent) 60%,transparent),
  radial-gradient(circle 0.9px at 47% 89%,color-mix(in srgb,var(--ink) 36%,transparent) 60%,transparent);
  --night-stars:radial-gradient(circle 0.9px at 78% 68%,color-mix(in srgb,var(--ink) 55%,transparent) 60%,transparent),
  radial-gradient(circle 1.6px at 31% 49%,color-mix(in srgb,var(--ink) 61%,transparent) 60%,transparent),
  radial-gradient(circle 1.4px at 30% 94%,color-mix(in srgb,var(--ink) 47%,transparent) 60%,transparent),
  radial-gradient(circle 1.3px at 18% 34%,color-mix(in srgb,var(--ink) 71%,transparent) 60%,transparent),
  radial-gradient(circle 1.4px at 94% 9%,color-mix(in srgb,var(--ink) 75%,transparent) 60%,transparent),
  radial-gradient(circle 1.2px at 86% 31%,color-mix(in srgb,var(--ink) 84%,transparent) 60%,transparent),
  radial-gradient(circle 1.7px at 50% 77%,color-mix(in srgb,var(--ink) 44%,transparent) 60%,transparent),
  radial-gradient(circle 0.9px at 93% 47%,color-mix(in srgb,var(--ink) 82%,transparent) 60%,transparent),
  radial-gradient(circle 1.9px at 72% 31%,color-mix(in srgb,var(--ink) 76%,transparent) 60%,transparent),
  radial-gradient(circle 1.8px at 81% 22%,color-mix(in srgb,var(--ink) 64%,transparent) 60%,transparent),
  radial-gradient(circle 1px at 35% 90%,color-mix(in srgb,var(--ink) 62%,transparent) 60%,transparent),
  radial-gradient(circle 1.1px at 13% 8%,color-mix(in srgb,var(--ink) 89%,transparent) 60%,transparent),
  radial-gradient(circle 1.3px at 63% 39%,color-mix(in srgb,var(--ink) 95%,transparent) 60%,transparent),
  radial-gradient(circle 1.8px at 24% 42%,color-mix(in srgb,var(--ink) 57%,transparent) 60%,transparent),
  radial-gradient(circle 1.6px at 81% 83%,color-mix(in srgb,var(--ink) 57%,transparent) 60%,transparent),
  radial-gradient(circle 1.9px at 97% 66%,color-mix(in srgb,var(--ink) 64%,transparent) 60%,transparent),
  radial-gradient(circle 1.5px at 6% 19%,color-mix(in srgb,var(--ink) 54%,transparent) 60%,transparent),
  radial-gradient(circle 1.1px at 3% 80%,color-mix(in srgb,var(--ink) 51%,transparent) 60%,transparent),
  radial-gradient(circle 1.5px at 2% 41%,color-mix(in srgb,var(--ink) 63%,transparent) 60%,transparent),
  radial-gradient(circle 1.4px at 33% 14%,color-mix(in srgb,var(--ink) 94%,transparent) 60%,transparent),
  radial-gradient(circle 1.3px at 61% 66%,color-mix(in srgb,var(--ink) 43%,transparent) 60%,transparent),
  radial-gradient(circle 1.7px at 88% 93%,color-mix(in srgb,var(--ink) 83%,transparent) 60%,transparent),
  radial-gradient(circle 1.3px at 44% 58%,color-mix(in srgb,var(--ink) 46%,transparent) 60%,transparent),
  radial-gradient(circle 1.3px at 47% 24%,color-mix(in srgb,var(--ink) 53%,transparent) 60%,transparent),
  radial-gradient(circle 0.8px at 13% 58%,color-mix(in srgb,var(--ink) 46%,transparent) 60%,transparent),
  radial-gradient(circle 1.5px at 57% 9%,color-mix(in srgb,var(--ink) 63%,transparent) 60%,transparent);
}

/* 本文のページ：淡い星、右上に青い光、左下に紫と薄紅の光 */
#stage .slide{background:var(--night-far),
  radial-gradient(ellipse 60% 60% at 100% 0,color-mix(in srgb,var(--accent) 34%,transparent),transparent 72%),
  radial-gradient(ellipse 56% 58% at 0 100%,color-mix(in srgb,var(--night-violet) 26%,transparent),transparent 72%),
  radial-gradient(ellipse 32% 34% at 20% 106%,color-mix(in srgb,var(--night-rose) 13%,transparent),transparent 70%),
  var(--night-sky)}

/* ## 見出し：左の余白に光る点、下に右へ消えていく線 */
#stage h2{position:relative;font-size:1.25em;line-height:1.3;font-weight:600;letter-spacing:.04em;color:var(--header);background:none;border:0;margin-top:0;margin-bottom:14px;padding:16px calc(var(--content-inset) + var(--text-pad)) 12px}
#stage h2::before{content:'';position:absolute;left:calc(var(--content-inset) + var(--text-pad) - 24px);top:35px;width:9px;height:9px;border-radius:50%;background:var(--accent);box-shadow:0 0 10px 2px color-mix(in srgb,var(--accent) 70%,transparent)}
#stage h2::after{content:'';position:absolute;left:calc(var(--content-inset) + var(--text-pad));right:0;bottom:0;height:1px;background:linear-gradient(90deg,var(--accent),transparent 75%)}

/* 表紙・章扉の夜空：たくさんの星、斜めに流れる天の川、右上の青い光、左下の紫と薄紅の光 */
#stage :is(.cover,.section-slide){background:var(--night-stars),
  linear-gradient(118deg,transparent 26%,color-mix(in srgb,var(--accent) 9%,transparent) 40%,color-mix(in srgb,var(--night-violet) 15%,transparent) 50%,color-mix(in srgb,var(--accent) 8%,transparent) 59%,transparent 72%),
  radial-gradient(ellipse 58% 70% at 92% 4%,color-mix(in srgb,var(--accent) 40%,transparent),transparent 70%),
  radial-gradient(ellipse 60% 64% at 0 100%,color-mix(in srgb,var(--night-violet) 32%,transparent),transparent 72%),
  radial-gradient(ellipse 34% 36% at 26% 108%,color-mix(in srgb,var(--night-rose) 17%,transparent),transparent 70%),
  var(--night-sky)}

/* 表紙：細い大きな題名、その上に光る短い線 */
#stage .cover{padding-top:0}
#stage .cover .cover-title{margin-top:155px;font-size:80px;font-weight:300;line-height:1.45;letter-spacing:.05em;color:var(--header)}
#stage .cover .cover-title::before{content:'';display:block;width:120px;height:2px;background:linear-gradient(90deg,var(--accent),transparent);box-shadow:0 0 8px color-mix(in srgb,var(--accent) 60%,transparent);margin:0 0 34px var(--text-pad)}
#stage .cover p{color:var(--accent);font-size:.75em;letter-spacing:.14em}
#stage .cover .cover-title p{color:inherit;font-size:inherit;letter-spacing:inherit}

/* # 章扉：細い字、白から水色へ移る文字 */
#stage .section-slide{padding:0 var(--content-inset);overflow:hidden}
#stage .section-slide h1{width:fit-content;margin-top:255px;padding-inline:var(--text-pad);font-size:76.8px;font-weight:300;line-height:1.4;letter-spacing:.06em;background:linear-gradient(90deg,var(--header) 30%,var(--accent));-webkit-background-clip:text;background-clip:text;color:transparent;caret-color:var(--header)}
#stage .chapter-number{color:var(--accent)}
#stage .section-slide h1::before{width:56px;height:2px;background:var(--accent);box-shadow:0 0 10px var(--accent);margin-bottom:30px}

/* 表：見出しの行を淡い光の色に */
#stage table{font-size:.85em;width:auto;max-width:100%;line-height:1.6;margin:0;border-collapse:collapse}
#stage table th{background:color-mix(in srgb,var(--accent) 12%,transparent);color:var(--header);font-weight:600;border-bottom:1px solid color-mix(in srgb,var(--accent) 50%,transparent)}
#stage table td{border-bottom:1px solid var(--rule)}

#stage .page-number{left:auto;right:10px;bottom:8px;font-size:13px;line-height:1.2;font-variant-numeric:tabular-nums;letter-spacing:.08em;color:var(--muted)}
#stage .slide::after{border:0}
#toolbar button{background:var(--paper);border:1px solid var(--rule);color:var(--ink)}
#overview,.thumb{background:var(--paper);color:var(--ink)}
.thumb{border-top-color:var(--accent)}
.thumb[aria-current=true]{outline:2px solid var(--accent);background:var(--paper)}
