cases.css:
/* solarized：クリーム色の方眼紙と青緑。見出しは左上から下がるタブ、章扉は qmd と同じ # を付ける。
   色の値は :root の変数だけに書き、ほかの色は変数から作る（テーマの色を直すと全体が付いてくる）。 */
:root {
  --ink: #3f555c;
  --link: #1f6fae;
  --accent: #006b83;
  --header: #0b4a57;
  --muted: #586e75;
  --warn: #a93625;
  --good: #526900;
  --mark: #efe1a0;
  --mark-ink: #51420c;
  --mark-line: #9b8427;
  --paper: #fdf6e3;
  --rule: #d4c8a8;
  --header-ink: #ffffff;
  --font-head: "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;
  --font-body: "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;
}
:root{--theme-ink:var(--ink);--theme-muted:var(--muted);--theme-accent:var(--accent);--theme-header:var(--header);--theme-rule:var(--rule);--theme-paper:var(--paper);--theme-border:var(--rule)}
.reveal{font-family:var(--font-body);color:var(--ink);font-size:29px;line-height:1.3}
#stage a{color:var(--link)}
#stage h3{font-size:1em;font-weight:650;color:var(--header)}

/* ## 見出し：左上から下がる、角の丸いタブ */
#stage h2{width:fit-content;max-width:calc(100% + var(--content-inset));font-size:1.2em;line-height:1.3;font-weight:650;color:var(--header);background:color-mix(in srgb,var(--accent) 11%,var(--paper));border:0;border-radius:0 0 18px 0;margin-top:0;margin-bottom:20px;padding:14px 40px 10px calc(var(--content-inset) + var(--text-pad))}

/* 表紙・章扉：方眼紙 */
#stage :is(.cover,.section-slide){background:
  linear-gradient(color-mix(in srgb,var(--rule) 45%,transparent) 1px,transparent 1px) 0 0/40px 40px,
  linear-gradient(90deg,color-mix(in srgb,var(--rule) 45%,transparent) 1px,transparent 1px) 0 0/40px 40px,
  var(--paper)}

/* 表紙：左端に青緑の柱、副題は等幅 */
#stage .cover{padding-top:0}
#stage .cover::before{content:'';position:absolute;left:0;top:0;bottom:0;width:16px;background:var(--accent)}
#stage .cover .cover-title{margin-top:150px;font-size:80px;font-weight:700;line-height:1.5;color:var(--header)}
#stage .cover p{color:var(--accent);font-family:"Menlo",monospace;font-size:.72em}
#stage .cover .cover-title p{color:inherit;font-family:inherit;font-size:inherit}

/* # 章扉：qmd の書き方と同じ # を前に */
#stage .section-slide{padding:0 var(--content-inset);overflow:hidden}
#stage .section-slide h1{margin-top:280px;padding-inline:var(--text-pad);font-size:74.4px;font-weight:700;line-height:1.4;color:var(--header)}
#stage .section-slide h1::before{content:'#';display:inline;width:auto;height:auto;margin:0 .35em 0 0;background:none;font-family:"Menlo",monospace;font-weight:400;color:var(--accent)}

/* 表：見出しの行をタブと同じ色、行は縞 */
#stage table{font-size:.85em;width:auto;max-width:100%;line-height:1.6;margin:0;border-collapse:collapse}
#stage table th{background:color-mix(in srgb,var(--accent) 11%,var(--paper));color:var(--header);font-weight:650;border-bottom:0}
#stage table td{border-bottom:0}
#stage table tbody tr:nth-child(even){background:color-mix(in srgb,var(--ink) 5%,var(--paper))}

#stage .page-number{left:auto;right:10px;bottom:8px;font-family:"Menlo",monospace;font-size:13px;line-height:1.2;color:var(--muted)}
#stage .slide::after{border:0}
#toolbar button{background:var(--paper);border:1px solid var(--rule);color:var(--ink)}
#overview,.thumb{background:var(--paper);color:var(--ink)}
.thumb{border-top-color:var(--accent)}
.thumb[aria-current=true]{outline:2px solid var(--accent);background:var(--paper)}
:root{--summary-paper:var(--paper);--summary-ink:var(--header)}
@media print{#stage .slide,#stage .slide *{-webkit-print-color-adjust:exact;print-color-adjust:exact}}

/* block palette v4: 整理・結論・補足・引用・定義・メモ */
:root {
  --block-border:3.5px solid #86918dff;
  --block-background:#fdf6e3ff;
  --block-plain-ink:#3f555cff;
  --block-plain-radius:10px;
  --block-plain-shadow:0.18;
  --block-top-line:8px solid #006b83ff;
  --block-top-fill:#cfe4e8ff;
  --block-top-ink:#3f555cff;
  --block-top-radius:10px;
  --block-top-shadow:0.18;
  --block-left-line:10px solid #526900ff;
  --block-left-fill:#dde3c4ff;
  --block-left-ink:#3f555cff;
  --block-left-radius:10px;
  --block-left-shadow:0.18;
  --block-quote-line:3.5px solid #586e75ff;
  --block-quote-fill:#dae0e2ff;
  --block-quote-ink:#3f555cff;
  --block-quote-radius:10px;
  --block-quote-shadow:0.18;
  --block-quote-accent:#586e75ff;
  --block-quote-width:3.5px;
  --block-bracket-line:3.5px solid #2c4996ff;
