cases.css:
/* terracotta：暖色の三色帯。表紙は濃色反転、章扉は右帯、通常ページは左帯。
   通常ページは細い帯と24pxの余白で本文を広く取り、脚注・ページ番号も本文領域内に収める。 */
:root {
  --ink: #3e362b;
  --link: #2d5f9e;
  --accent: #a6543c;
  --header: #432e26;
  --muted: #72675a;
  --warn: #b03a12;
  --good: #366841;
  --mark: #f3dfa5;
  --mark-ink: #523a13;
  --mark-line: #aa8335;
  --paper: #f8f4ea;
  --rule: #cbbfa9;
  --header-ink: #fff8ed;
  --gold: #c3a078;
  --band-soft: #b99077;
  --band-width: 64px;
  --font-head: "Hiragino Mincho ProN","Yu Mincho",serif;
  --font-body: "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;
}
:root{--theme-ink:var(--ink);--theme-muted:var(--muted);--theme-accent:var(--accent);--theme-header:var(--header);--theme-rule:var(--rule);--theme-paper:var(--paper);--theme-border:var(--rule)}

.reveal{font-family:var(--font-body);color:var(--ink);font-size:29px;line-height:1.3}
#stage a{color:var(--link)}
#stage :is(h1,h2,h3,.cover-title){font-family:var(--font-head)}
#stage h3{font-size:1em;font-weight:600;color:var(--header)}

/* ## 通常ページ：左帯と、帯から離した見出し・本文。 */
#stage .slide{
  --safe-left:calc(var(--band-width) + 44px);
  --safe-right:56px;
  padding:28px var(--safe-right) 64px var(--safe-left);
  box-sizing:border-box;
  background:var(--paper);
  box-shadow:none;
}
#stage .slide:not(.cover):not(.section-slide){
  --band-width:20px;
  --safe-left:calc(var(--band-width) + 24px);
  --safe-right:32px;
  padding-top:8px; /* 図の多いページでも本文が下の脚注・引用に届かないように */
}
#stage .slide::before{
  content:'';position:absolute;left:0;right:auto;top:0;bottom:0;
  width:var(--band-width);pointer-events:none;
  background:linear-gradient(to bottom,var(--header) 0 18%,var(--gold) 18% 24%,var(--band-soft) 24% 100%);
  border:0;
}
#stage .slide::after{content:none;border:0}
#stage .slide > h2{
  position:relative;margin:0 0 18px;padding:12px var(--text-pad) 20px;
  width:auto;max-width:none;font-size:1.25em;line-height:1.35;
  font-weight:600;letter-spacing:.04em;color:var(--header);
  border:0;border-radius:0;background:none;box-shadow:none;
}
