  --block-quote-radius:10px;
  --block-quote-shadow:0.18;
  --block-quote-accent:#72675aff;
  --block-quote-width:3.5px;
  --block-bracket-line:3.5px solid #7c6f46ff;
  --block-bracket-fill:#e0ddd4ff;
  --block-bracket-ink:#3e362bff;
  --block-bracket-radius:0px;
  --block-bracket-shadow:0.18;
  --block-bracket-accent:#7c6f46ff;
  --block-bracket-width:3.5px;
  --block-fold-line:3.5px solid #9a7730ff;
  --block-fold-fill:#e4dccbff;
  --block-fold-ink:#3e362bff;
  --block-fold-radius:10px;
  --block-fold-shadow:0.18;
  --block-fold-accent:#9a7730ff;
  --block-fold-width:3.5px;
  --block-unframed-radius:0px; --block-unframed-shadow:0.18;
}

/* 表紙の既定位置（タイトルの上余白・発表者までの間隔） */
#stage .slide.cover { --cover-title-top:0px; --cover-authors-gap:36px; }
#stage .slide.cover .cover-title { margin-top:var(--cover-title-top); left:0; top:0; }
#stage .slide.cover .cover-subtitle { left:0; top:0; }
#stage .slide.cover .cover-authors { margin-top:var(--cover-authors-gap); left:0; top:0; }

/* slide-studio table header */
#stage table { --header: #432e26; }

/* slide-studio title header */
#stage .slide:is(.cover, .section-slide) { --header: #432e26; }

/* slide-studio heading options */
:root { --heading-mode: fill; --heading-rule-style: solid; --heading-rule-width: 2px; --heading-rule-inset: 44px; }
#stage .slide > h2 { margin-inline:calc(-1 * var(--content-inset)); width:auto; max-width:none; padding-inline:calc(var(--content-inset) + var(--text-pad)); border-radius:0; }
#stage .slide > h2 { background:var(--header-fill, var(--header)); border:0; box-shadow:none; }
#stage .slide > h2, #stage .slide > h2 * { color:var(--header-ink); }
#stage .slide > h2::after { display:none; }
/* end heading options */

/* slide-studio heading fill */
:root { --header-fill: var(--header); }
#stage h2 { background: var(--header-fill); }
#stage h2, #stage h2 * { color: var(--header-ink); }
#stage .cover .cover-title, #stage .cover .cover-title p { color: var(--header); }
